use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::{AtomicBool,AtomicU64,Ordering};use js_runtime::{Runtime,Value,PropertyKey};
struct Counting;static ACTIVE:AtomicBool=AtomicBool::new(false);static ALLOCS:AtomicU64=AtomicU64::new(0);static REALLOCS:AtomicU64=AtomicU64::new(0);static BYTES:AtomicU64=AtomicU64::new(0);
unsafe impl GlobalAlloc for Counting{unsafe fn alloc(&self,layout:Layout)->*mut u8{if ACTIVE.load(Ordering::Relaxed){ALLOCS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(layout.size()as u64,Ordering::Relaxed);}unsafe{System.alloc(layout)}}unsafe fn alloc_zeroed(&self,layout:Layout)->*mut u8{if ACTIVE.load(Ordering::Relaxed){ALLOCS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(layout.size()as u64,Ordering::Relaxed);}unsafe{System.alloc_zeroed(layout)}}unsafe fn dealloc(&self,p:*mut u8,layout:Layout){unsafe{System.dealloc(p,layout)}}unsafe fn realloc(&self,p:*mut u8,layout:Layout,size:usize)->*mut u8{if ACTIVE.load(Ordering::Relaxed){REALLOCS.fetch_add(1,Ordering::Relaxed);BYTES.fetch_add(size as u64,Ordering::Relaxed);}unsafe{System.realloc(p,layout,size)}}}
#[global_allocator]static ALLOCATOR:Counting=Counting;
fn start(){ALLOCS.store(0,Ordering::Relaxed);REALLOCS.store(0,Ordering::Relaxed);BYTES.store(0,Ordering::Relaxed);ACTIVE.store(true,Ordering::Relaxed)}fn end()->(u64,u64,u64){ACTIVE.store(false,Ordering::Relaxed);(ALLOCS.load(Ordering::Relaxed),REALLOCS.load(Ordering::Relaxed),BYTES.load(Ordering::Relaxed))}
fn runtime(enabled:bool)->Runtime{let mut rt=Runtime::new();rt.numeric_property_key_cache_enabled=enabled;rt.index_string_fast_path_enabled=enabled;rt}
fn keys(rt:&mut Runtime)->Vec<PropertyKey>{(0..32).map(|i|{let expected=PropertyKey(rt.intern(&i.to_string()));assert_eq!(rt.index_property_key(i),expected);expected}).collect()}
fn main(){for enabled in[false,true]{let mut rt=runtime(enabled);let keys=keys(&mut rt);let mut checksum=0u64;start();for index in 0..100_000usize{let expected=keys[index&31];let key=rt.index_property_key(std::hint::black_box(index&31));assert_eq!(key,expected);checksum=checksum.wrapping_mul(31).wrapping_add(key.0.0 as u64);}let(a,r,b)=end();println!("{{\"case\":\"canonical-index\",\"enabled\":{enabled},\"iterations\":100000,\"allocations\":{a},\"reallocations\":{r},\"requestedBytes\":{b},\"checksum\":\"{checksum}\"}}");}
for sparse in[false,true]{for enabled in[false,true]{let mut rt=runtime(enabled);let keys=keys(&mut rt);let items=(0..8).map(|i|if sparse&&i%2==1{None}else{Some(Value::Number(i as f64))}).collect::<Vec<_>>();let _=rt.array(&items);let mut checksum=0u64;let mut last=Value::Undefined;start();for _ in 0..1000{last=rt.array(&items);for(index,item)in items.iter().enumerate(){if let Some(Value::Number(expected))=item{let Value::Number(actual)=rt.get(last,keys[index]).unwrap()else{panic!()};assert_eq!(actual.to_bits(),expected.to_bits());checksum=checksum.wrapping_mul(31).wrapping_add(actual.to_bits());}else{assert!(!rt.has_own_property(last,keys[index]).unwrap());}}}let(a,r,b)=end();let names=rt.own_keys(last,true).unwrap();let expected=items.iter().enumerate().filter_map(|(i,item)|item.map(|_|Value::String(keys[i].0))).collect::<Vec<_>>();assert_eq!(names,expected);println!("{{\"case\":\"array\",\"sparse\":{sparse},\"enabled\":{enabled},\"iterations\":1000,\"allocations\":{a},\"reallocations\":{r},\"requestedBytes\":{b},\"checksum\":\"{checksum}\"}}");}}}
